import Database from 'better-sqlite3';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const dbPath = path.join(__dirname, '..', 'stocklab.db');

const db = new Database(dbPath);

db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');

function tableColumns(table: string): string[] {
  return (db.prepare(`PRAGMA table_info(${table})`).all() as any[]).map((c: any) => c.name);
}

function addColumnIfMissing(table: string, column: string, definition: string): void {
  if (!tableColumns(table).includes(column)) {
    db.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`);
  }
}

/**
 * Non-destructive migrations: add new columns while keeping every existing
 * table and its data intact. Safe to run on every startup.
 */
function runMigrations(): void {
  addColumnIfMissing('users', 'firebase_uid', 'TEXT');
  addColumnIfMissing('users', 'provider', 'TEXT');
  addColumnIfMissing('users', 'last_login_at', 'TEXT');

  // Stock discovery / real market-data fields.
  addColumnIfMissing('stocks', 'exchange', 'TEXT');
  addColumnIfMissing('stocks', 'provider', 'TEXT');
  addColumnIfMissing('stocks', 'provider_symbol', 'TEXT');
  addColumnIfMissing('stocks', 'country', 'TEXT');
  addColumnIfMissing('stocks', 'currency', 'TEXT');
  addColumnIfMissing('stocks', 'asset_type', 'TEXT');
  addColumnIfMissing('stocks', 'last_market_data_at', 'TEXT');
  addColumnIfMissing('stocks', 'data_status', 'TEXT');
  addColumnIfMissing('market_data', 'quote_time', 'TEXT');
  addColumnIfMissing('market_data', 'data_status', 'TEXT');

  db.exec(`CREATE UNIQUE INDEX IF NOT EXISTS idx_users_firebase_uid ON users(firebase_uid);`);
  db.exec(`CREATE UNIQUE INDEX IF NOT EXISTS idx_stocks_provider_key ON stocks(provider, provider_symbol);`);

  // Mark the status of any data currently stored. Stocks that were seeded with
  // market_data rows retain those as legitimate last-known data. Without a
  // configured provider their latest data is treated as CACHED (stale at best).
  db.prepare(`
    UPDATE stocks SET data_status = COALESCE(data_status, 'CACHED')
    WHERE provider IS NOT NULL AND provider_symbol IS NOT NULL
  `).run();

  // Link existing Indian stocks to the Alpha Vantage provider so they can be
  // refreshed with real data once an API key is configured. This maps the local
  // pre-seeded symbols to their provider symbols (NSE -> .NS, BSE -> .BO).
  db.prepare(`
    UPDATE stocks
    SET provider = COALESCE(provider, 'alpha_vantage'),
        provider_symbol = COALESCE(provider_symbol,
          CASE WHEN exchange = 'BSE' THEN symbol || '.BO' ELSE symbol || '.NS' END)
    WHERE provider IS NULL OR provider_symbol IS NULL
  `).run();

  // Existing stocks keep their exchange label.
  db.prepare(`UPDATE stocks SET exchange = COALESCE(exchange, 'NSE') WHERE exchange IS NULL`).run();
}

export function initializeDatabase() {
  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id TEXT PRIMARY KEY,
      email TEXT UNIQUE NOT NULL,
      name TEXT NOT NULL,
      password_hash TEXT,
      google_id TEXT,
      avatar_url TEXT,
      cash_balance REAL NOT NULL DEFAULT 500.0,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE TABLE IF NOT EXISTS stocks (
      symbol TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      sector TEXT,
      description TEXT,
      market_cap TEXT,
      pe_ratio REAL,
      dividend_yield REAL,
      fifty_two_week_high REAL,
      fifty_two_week_low REAL,
      last_updated TEXT DEFAULT (datetime('now')),
      exchange TEXT,
      provider TEXT,
      provider_symbol TEXT,
      country TEXT,
      currency TEXT,
      asset_type TEXT,
      last_market_data_at TEXT,
      data_status TEXT
    );

    CREATE TABLE IF NOT EXISTS market_data (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      symbol TEXT NOT NULL,
      price REAL NOT NULL,
      change_amount REAL,
      change_percent REAL,
      volume INTEGER,
      high REAL,
      low REAL,
      open REAL,
      previous_close REAL,
      timestamp TEXT NOT NULL DEFAULT (datetime('now')),
      quote_time TEXT,
      data_status TEXT,
      FOREIGN KEY (symbol) REFERENCES stocks(symbol)
    );

    CREATE TABLE IF NOT EXISTS price_history (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      symbol TEXT NOT NULL,
      date TEXT NOT NULL,
      price REAL NOT NULL,
      volume INTEGER,
      open REAL,
      high REAL,
      low REAL,
      source TEXT,
      fetched_at TEXT NOT NULL DEFAULT (datetime('now')),
      FOREIGN KEY (symbol) REFERENCES stocks(symbol),
      UNIQUE(symbol, date)
    );

    CREATE TABLE IF NOT EXISTS holdings (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      symbol TEXT NOT NULL,
      quantity INTEGER NOT NULL DEFAULT 0,
      avg_purchase_price REAL NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id),
      FOREIGN KEY (symbol) REFERENCES stocks(symbol),
      UNIQUE(user_id, symbol)
    );

    CREATE TABLE IF NOT EXISTS transactions (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      symbol TEXT NOT NULL,
      type TEXT NOT NULL CHECK(type IN ('buy', 'sell')),
      quantity INTEGER NOT NULL,
      price REAL NOT NULL,
      total_value REAL NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id),
      FOREIGN KEY (symbol) REFERENCES stocks(symbol)
    );

    CREATE TABLE IF NOT EXISTS watchlist (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      symbol TEXT NOT NULL,
      added_at TEXT NOT NULL DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id),
      FOREIGN KEY (symbol) REFERENCES stocks(symbol),
      UNIQUE(user_id, symbol)
    );

    CREATE TABLE IF NOT EXISTS lessons (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      slug TEXT UNIQUE NOT NULL,
      content TEXT NOT NULL,
      order_index INTEGER NOT NULL,
      category TEXT DEFAULT 'basics'
    );

    CREATE TABLE IF NOT EXISTS quiz_questions (
      id TEXT PRIMARY KEY,
      lesson_id TEXT NOT NULL,
      question TEXT NOT NULL,
      options TEXT NOT NULL,
      correct_index INTEGER NOT NULL,
      explanation TEXT,
      order_index INTEGER NOT NULL,
      FOREIGN KEY (lesson_id) REFERENCES lessons(id)
    );

    CREATE TABLE IF NOT EXISTS quiz_results (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      lesson_id TEXT NOT NULL,
      score INTEGER NOT NULL,
      total INTEGER NOT NULL,
      completed_at TEXT NOT NULL DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id),
      FOREIGN KEY (lesson_id) REFERENCES lessons(id)
    );

    CREATE TABLE IF NOT EXISTS achievements (
      id TEXT PRIMARY KEY,
      user_id TEXT NOT NULL,
      badge_id TEXT NOT NULL,
      earned_at TEXT NOT NULL DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id),
      UNIQUE(user_id, badge_id)
    );

    CREATE INDEX IF NOT EXISTS idx_holdings_user ON holdings(user_id);
    CREATE INDEX IF NOT EXISTS idx_transactions_user ON transactions(user_id);
    CREATE INDEX IF NOT EXISTS idx_watchlist_user ON watchlist(user_id);
    CREATE INDEX IF NOT EXISTS idx_market_data_symbol ON market_data(symbol);
    CREATE INDEX IF NOT EXISTS idx_market_data_timestamp ON market_data(timestamp);
    CREATE INDEX IF NOT EXISTS idx_price_history_symbol ON price_history(symbol, date);
  `);

  runMigrations();
  seedStocks();
  seedLessons();
}

function symbolHash(symbol: string): number {
  let h = 2166136261;
  for (let i = 0; i < symbol.length; i++) {
    h ^= symbol.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

